    private int dp(float n){return Ui.dp(activity,n);}
    private void load(){spec.shortSide=Prefs.of(activity).getInt(spec.gif?"gif_resolution":"record_resolution",spec.gif?240:720);spec.audio=spec.gif?"silent":Prefs.of(activity).getString("recording_mode","silent");spec.hide=Prefs.of(activity).getBoolean("record_hide",false);spec.size();}
