    private void add(View v,WindowManager.LayoutParams p){p.setTitle("空叶录制准备:"+v.getContentDescription());wm.addView(v,p);views.add(v);}
    void show(){remove();ThemePolicy.apply(activity);spec.size();crop=new ResizableCropView(activity,null,true);crop.setContentDescription(spec.gif?"GIF 录制选区":"录屏选区");crop.setInitial(spec.crop,spec.screenW,spec.screenH);crop.setChanged(area->{spec.crop.set(Math.round(area.left),Math.round(area.top),Math.round(area.right),Math.round(area.bottom));spec.size();if(!resizing)position();});add(crop,params(-1,-1,0,0,true));if(!spec.watermark.isBlank()){float factor=Math.min(1f,720f/Math.max(spec.crop.width(),spec.crop.height()));previewPixels=RecordingWatermark.render(spec.watermark,Math.max(1,Math.round(spec.crop.width()*factor)),Math.max(1,Math.round(spec.crop.height()*factor)));watermarkPreview=new ImageView(activity);watermarkPreview.setContentDescription("录制水印位置预览");watermarkPreview.setImageBitmap(previewPixels);watermarkPreview.setScaleType(ImageView.ScaleType.FIT_XY);add(watermarkPreview,params(spec.crop.width(),spec.crop.height(),spec.crop.left,spec.crop.top,true));}int[] modes={CropGeometry.LEFT|CropGeometry.TOP,CropGeometry.TOP,CropGeometry.RIGHT|CropGeometry.TOP,CropGeometry.RIGHT,CropGeometry.RIGHT|CropGeometry.BOTTOM,CropGeometry.BOTTOM,CropGeometry.LEFT|CropGeometry.BOTTOM,CropGeometry.LEFT,CropGeometry.MOVE};String[] labels={"调整录制左上角","调整录制上边","调整录制右上角","调整录制右边","调整录制右下角","调整录制下边","调整录制左下角","调整录制左边","移动录制区域"};for(int i=0;i<modes.length;i++){View v=new View(activity);v.setContentDescription(labels[i]);int mode=modes[i];v.setOnTouchListener(new View.OnTouchListener(){float x,y;float[] before;public boolean onTouch(View v,MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN->{resizing=true;x=e.getRawX();y=e.getRawY();before=new float[]{spec.crop.left,spec.crop.top,spec.crop.right,spec.crop.bottom};return true;}case MotionEvent.ACTION_MOVE,MotionEvent.ACTION_UP->{float[] r=CropGeometry.adjust(before,mode,e.getRawX()-x,e.getRawY()-y,spec.screenW,spec.screenH,dp(40));spec.crop.set(Math.round(r[0]),Math.round(r[1]),Math.round(r[2]),Math.round(r[3]));crop.area.set(spec.crop);crop.invalidate();spec.size();if(e.getActionMasked()==MotionEvent.ACTION_UP){resizing=false;position();receipt();v.performClick();}return true;}case MotionEvent.ACTION_CANCEL->{resizing=false;position();return true;}}return true;}});handles.add(v);add(v,params(dp(48),dp(48),0,0,false));}position();
        View back=button("back","关闭录制准备",close,0xEE153546);add(back,params(dp(48),dp(48),dp(12),dp(38),false));
        LinearLayout bar=Ui.row(activity);bar.setContentDescription(spec.gif?"GIF 录制工具栏":"录屏工具栏");Ui.pad(bar,6,6,6,6);bar.setBackground(Ui.bg(0xEE101C2B,38,activity));bar.addView(button("resolution","录制分辨率",this::resolution,0),new LinearLayout.LayoutParams(0,dp(52),1));bar.addView(button("region","录制全屏",()->{spec.crop.set(0,0,spec.screenW,spec.screenH);show();},0),new LinearLayout.LayoutParams(0,dp(52),1));if(!spec.gif)bar.addView(button("watermark","录制水印",this::watermark,0),new LinearLayout.LayoutParams(0,dp(52),1));bar.addView(button(spec.gif?"gif_record":"record",spec.gif?"开始录制 GIF":"开始录屏",start,0xFF0099D7),new LinearLayout.LayoutParams(dp(64),dp(64)));if(!spec.gif)bar.addView(button("gif_record","切换到 GIF 录制",()->switchMode(true),0),new LinearLayout.LayoutParams(0,dp(52),1));if(spec.gif)bar.addView(button("record","切换到录屏",()->switchMode(false),0),new LinearLayout.LayoutParams(0,dp(52),1));bar.addView(button("hide","录制时隐藏图标",this::hideIcon,0),new LinearLayout.LayoutParams(0,dp(52),1));bar.addView(button(spec.gif?"watermark":"audio",spec.gif?"录制水印":"录制声音",spec.gif?this::watermark:this::audio,0),new LinearLayout.LayoutParams(0,dp(52),1));WindowManager.LayoutParams bp=params(spec.screenW-dp(24),dp(78),dp(12),spec.screenH-dp(165),false);bp.flags&=~WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE;bar.setFocusableInTouchMode(true);bar.setOnKeyListener((v,key,event)->{if(key==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP)close.run();return true;}return false;});add(bar,bp);receipt();}
    private View button(String icon,String label,Runnable action,int color){FrameLayout v=new FrameLayout(activity);v.setContentDescription(label);if(color!=0)v.setBackground(Ui.bg(color,100,activity));v.addView(Ui.icon(activity,icon,Color.WHITE,24),new FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER));v.setOnClickListener(w->action.run());return v;}
    private void position(){if(watermarkPreview!=null){WindowManager.LayoutParams wp=(WindowManager.LayoutParams)watermarkPreview.getLayoutParams();wp.x=spec.crop.left;wp.y=spec.crop.top;wp.width=spec.crop.width();wp.height=spec.crop.height();wm.updateViewLayout(watermarkPreview,wp);}if(crop==null||handles.size()!=9)return;float[][] e=crop.points(),p=Arrays.copyOf(e,9);p[8]=new float[]{spec.crop.exactCenterX(),spec.crop.exactCenterY()};for(int i=0;i<9;i++){View v=handles.get(i);WindowManager.LayoutParams at=(WindowManager.LayoutParams)v.getLayoutParams();at.x=Math.max(0,Math.min(spec.screenW-dp(48),Math.round(p[i][0])-dp(24)));at.y=Math.max(dp(25),Math.min(spec.screenH-dp(48),Math.round(p[i][1])-dp(24)));try{wm.updateViewLayout(v,at);}catch(IllegalArgumentException ignored){}}}
    private void switchMode(boolean gif){spec.gif=gif;load();show();}
    private void dialogFocus(boolean focused){if(focused)activity.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE);else activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE);}
    private void closeChoices(){if(choices!=null){try{wm.removeView(choices);}catch(IllegalArgumentException ignored){}choices=null;}}
    private void dialog(String title,String[] options,int selected,java.util.function.IntConsumer change){
        closeChoices();LinearLayout list=Ui.card(activity);list.setContentDescription(title+"直接选择");Ui.pad(list,8,8,8,8);list.setElevation(dp(12));
        TextView head=Ui.text(activity,title,13,Ui.MUTED,true);head.setGravity(Gravity.CENTER_VERTICAL);Ui.pad(head,12,0,12,0);list.addView(head,new LinearLayout.LayoutParams(-1,dp(34)));
        for(int i=0;i<options.length;i++){int index=i;boolean on=i==selected;LinearLayout option=Ui.row(activity);option.setContentDescription(options[i]);option.setSelected(on);Ui.pad(option,12,0,12,0);option.setBackground(Ui.ripple(activity,on?Ui.PALE:0,12));option.addView(Ui.text(activity,options[i],15,on?Ui.GREEN:Ui.INK,on),new LinearLayout.LayoutParams(0,-2,1));if(on)option.addView(Ui.icon(activity,"check",Ui.GREEN,18));option.setOnClickListener(v->{change.accept(index);closeChoices();show();});list.addView(option,new LinearLayout.LayoutParams(-1,dp(46)));}
        list.setFocusableInTouchMode(true);list.setOnKeyListener((v,key,event)->{if(key==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP)closeChoices();return true;}return false;});list.setOnTouchListener((v,event)->{if(event.getActionMasked()==MotionEvent.ACTION_OUTSIDE){closeChoices();return true;}return false;});int height=dp(16+34+options.length*46);WindowManager.LayoutParams p=params(Math.min(dp(320),spec.screenW-dp(32)),height,dp(16),Math.max(dp(90),spec.screenH-dp(173)-height),false);p.flags&=~WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE;p.flags|=WindowManager.LayoutParams.FLAG_WATCH_OUTSIDE_TOUCH;p.setTitle("空叶录制选项:"+title);wm.addView(list,p);choices=list;list.requestFocus();
    }
    private void resolution(){int[] sizes=spec.gif?new int[]{160,240,360}:new int[]{360,480,720,1080};String[] labels=new String[sizes.length];int selected=0;for(int i=0;i<sizes.length;i++){labels[i]=sizes[i]+"p 上限";if(sizes[i]==spec.shortSide)selected=i;}dialog("录制分辨率",labels,selected,index->{spec.shortSide=sizes[index];Prefs.of(activity).edit().putInt(spec.gif?"gif_resolution":"record_resolution",spec.shortSide).apply();});}
    private void audio(){String[] ids=Build.VERSION.SDK_INT>=29?new String[]{"silent","internal","microphone","both"}:new String[]{"silent","microphone"};String[] names=Build.VERSION.SDK_INT>=29?new String[]{"无声","手机内部声音","麦克风","内部声音 + 麦克风"}:new String[]{"无声","麦克风"};int selected=Arrays.asList(ids).indexOf(spec.audio);dialog("录制声音",names,Math.max(0,selected),index->{spec.audio=ids[index];Prefs.of(activity).edit().putString("recording_mode",spec.audio).apply();});}
    private void hideIcon(){dialog("录制时隐藏图标",new String[]{"显示录制控制图标","隐藏图标，通过通知控制"},spec.hide?1:0,index->{spec.hide=index==1;Prefs.of(activity).edit().putBoolean("record_hide",spec.hide).apply();});}
    private void watermark(){
        visible(false);dialogFocus(true);
        float scale=Math.min(1f,720f/Math.max(spec.crop.width(),spec.crop.height()));
        watermarkBitmap=Bitmap.createBitmap(Math.max(1,Math.round(spec.crop.width()*scale)),Math.max(1,Math.round(spec.crop.height()*scale)),Bitmap.Config.ARGB_8888);
        watermarkCanvas=new ImageEditView(activity,watermarkBitmap);watermarkCanvas.setContentDescription("录制水印编辑画布");watermarkCanvas.color(Color.WHITE);watermarkCanvas.width(2);watermarkCanvas.tool("text");watermarkCanvas.onTextDone(this::finishWatermark);watermarkCanvas.loadWatermark(spec.watermark);
        FrameLayout frame=new FrameLayout(activity){@Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getKeyCode()==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP){if(watermarkCanvas.isTyping())watermarkCanvas.finishText();else finishWatermark();}return true;}return super.dispatchKeyEvent(event);}};FrameLayout.LayoutParams canvasAt=new FrameLayout.LayoutParams(spec.crop.width(),spec.crop.height());canvasAt.leftMargin=spec.crop.left;canvasAt.topMargin=spec.crop.top;frame.addView(watermarkCanvas,canvasAt);
        LinearLayout bar=Ui.row(activity);bar.setBackground(Ui.bg(0xEE153546,28,activity));Ui.pad(bar,6,4,6,4);
        bar.addView(button("text","添加水印文字",()->watermarkCanvas.tool("text"),0),new LinearLayout.LayoutParams(0,dp(44),1));
        for(int color:new int[]{Color.WHITE,Color.BLACK,0xFFF44336,0xFFFFD32A}){View swatch=new View(activity);android.graphics.drawable.GradientDrawable dot=Ui.bg(color,100,activity);dot.setStroke(dp(2),0x66FFFFFF);swatch.setBackground(dot);swatch.setContentDescription("水印颜色"+(color==Color.WHITE?"白色":color==Color.BLACK?"黑色":color==0xFFF44336?"红色":"黄色"));swatch.setOnClickListener(v->{if(watermarkCanvas!=null)watermarkCanvas.textColor(color);});LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(dp(24),dp(24));sp.setMargins(dp(5),0,dp(5),0);bar.addView(swatch,sp);}
        bar.addView(button("check","完成水印编辑",this::finishWatermark,0),new LinearLayout.LayoutParams(0,dp(44),1));
        FrameLayout.LayoutParams barAt=new FrameLayout.LayoutParams(spec.screenW-dp(24),dp(54));barAt.leftMargin=dp(12);barAt.topMargin=dp(38);frame.addView(bar,barAt);WindowManager.LayoutParams cp=params(-1,-1,0,0,false);cp.flags&=~WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE;cp.softInputMode=WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING;cp.setTitle("空叶录制水印画布");ImageEditView currentEditor=watermarkCanvas;frame.setOnApplyWindowInsetsListener((view,insets)->{if(watermarkCanvas!=currentEditor||!view.isAttachedToWindow())return insets;int bottom=Build.VERSION.SDK_INT>=30?insets.getInsets(WindowInsets.Type.ime()).bottom:insets.getSystemWindowInsetBottom();FrameLayout.LayoutParams at=(FrameLayout.LayoutParams)watermarkCanvas.getLayoutParams();at.height=bottom>0?Math.max(dp(100),Math.min(spec.crop.height(),spec.screenH-bottom-spec.crop.top)):spec.crop.height();watermarkCanvas.setLayoutParams(at);return insets;});wm.addView(frame,cp);watermarkView=frame;frame.requestApplyInsets();
    }
    private void finishWatermark(){if(returningFromWatermark)return;returningFromWatermark=true;try{ImageEditView editor=watermarkCanvas;if(editor!=null)spec.watermark=editor.watermark();closeWatermark();dialogFocus(false);if(!activity.isFinishing()&&!activity.isDestroyed())show();}finally{returningFromWatermark=false;}}
    private void closeWatermark(){ImageEditView editor=watermarkCanvas;View overlay=watermarkView,bar=watermarkBar;watermarkCanvas=null;watermarkView=watermarkBar=null;if(editor!=null)editor.finishText();for(View v:new View[]{bar,overlay})if(v!=null){activity.getSystemService(android.view.inputmethod.InputMethodManager.class).hideSoftInputFromWindow(v.getWindowToken(),0);try{wm.removeViewImmediate(v);}catch(IllegalArgumentException ignored){}}if(editor!=null)editor.dispose();if(watermarkBitmap!=null){watermarkBitmap.recycle();watermarkBitmap=null;}}
    void restore(RecordingSpec old){float sx=spec.screenW/(float)Math.max(1,old.screenW),sy=spec.screenH/(float)Math.max(1,old.screenH);spec.crop.set(Math.round(old.crop.left*sx),Math.round(old.crop.top*sy),Math.round(old.crop.right*sx),Math.round(old.crop.bottom*sy));spec.gif=old.gif;spec.shortSide=old.shortSide;spec.hide=old.hide;spec.audio=old.audio;spec.watermark=old.watermark;spec.size();}
    void visible(boolean visible){if(!visible)closeChoices();for(View v:views)v.setVisibility(visible?View.VISIBLE:View.INVISIBLE);}
    private void receipt(){Prefs.of(activity).edit().putString("record_setup_kind",spec.gif?"gif":"video").putInt("record_setup_left",spec.crop.left).putInt("record_setup_top",spec.crop.top).putInt("record_setup_right",spec.crop.right).putInt("record_setup_bottom",spec.crop.bottom).putInt("record_setup_width",spec.width).putInt("record_setup_height",spec.height).apply();}
    void remove(){closeChoices();closeWatermark();for(View v:views)try{wm.removeView(v);}catch(IllegalArgumentException ignored){}views.clear();handles.clear();crop=null;watermarkPreview=null;if(previewPixels!=null){previewPixels.recycle();previewPixels=null;}}
